function classificationTerms(record){return [record.name,planetName(record.name),record.nickname,...(record.aliases||[]),record.type,record.bodyType,record.tag,record.category,record.status,/ruin|wreck|destroyed/i.test(record.status||'')?'ruins ruined wrecks destroyed historical':'',record.affiliation,record.kind,record.centralBodyType,EXOTIC_TYPES[record.centralBodyType],record.tier?'Tier '+record.tier:'',TIER_NAMES[record.tier],record.silentPresence?'Silent infested':'',record.centralBodyType==='silent-darkened'?'Dead star dead system':'',record.capital,...(record.links||[])]}
